// NOTE: Since we don't have actual env keys here, we use a robust local fallback system.
// In a real app, you'd use createClient from '@supabase/supabase-js'.

const STORAGE_KEY = 'sofia_ai_local_db';

const getLocalDb = () => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : { users: {}, transactions: [], logs: [] };
};

const saveLocalDb = (data: any) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
};

export const supabase = {
  auth: {
    getUser: () => ({ data: { user: { id: 'dev-user', email: 'user@sofia.ai' } }, error: null }),
  },
  from: (table: string) => ({
    select: (query: string = '*') => ({
      eq: (col: string, val: any) => ({
        single: () => {
          const db = getLocalDb();
          if (table === 'profiles') return { data: db.users[val] || { id: val, tokens: 10, role: 'admin' }, error: null };
          return { data: null, error: 'Not found' };
        }
      }),
      order: (col: string, { ascending = false } = {}) => ({
        data: [],
        error: null
      })
    }),
    update: (data: any) => ({
      eq: (col: string, val: any) => {
        const db = getLocalDb();
        if (table === 'profiles') db.users[val] = { ...db.users[val], ...data };
        saveLocalDb(db);
        return { error: null };
      }
    }),
    insert: (data: any) => {
      const db = getLocalDb();
      if (table === 'transactions') db.transactions.push(data);
      saveLocalDb(db);
      return { error: null };
    }
  })
};

import { GoogleGenAI, Type } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const chatStream = async (message: string, history: { role: string; content: string }[], onChunk: (text: string) => void) => {
  const ai = getAI();
  const chat = ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: "Tu es SOFIA AI, une assistante intelligente premium. Réponds avec élégance et précision.",
    }
  });

  const response = await chat.sendMessageStream({ message });
  for await (const chunk of response) {
    onChunk(chunk.text || '');
  }
};

export const generateImage = async (prompt: string, base64Image?: string) => {
  const ai = getAI();
  const parts: any[] = [{ text: prompt }];
  if (base64Image) {
    parts.push({
      inlineData: {
        data: base64Image,
        mimeType: 'image/png'
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: { parts },
  });

  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      return `data:image/png;base64,${part.inlineData.data}`;
    }
  }
  return null;
};

export const scolaireAnalysis = async (prompt: string, fileData?: { data: string; mimeType: string }) => {
  const ai = getAI();
  const parts: any[] = [{ text: prompt }];
  if (fileData) {
    parts.push({
      inlineData: fileData
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: { parts },
    config: {
      systemInstruction: "Tu es un expert scolaire. Utilise LaTeX pour les mathématiques. Formate tes réponses pour un PDF premium.",
    }
  });

  return response.text;
};

export const translateText = async (text: string, targetLang: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Translate the following text to ${targetLang}: "${text}"`,
  });
  return response.text;
};

